/**
 * Signals in message BootloaderRequest.
 *
 * Uploader to bootloader. Byte 0 selects the command. Set unused bytes to zero; pad the final DATA frame payload with 0xFF.
 *
 * All signal values are as on the CAN bus.
 */
struct bootloader_bootloader_request_t {
    /**
     * INFO=0, BEGIN=1, DATA=2, END=3, RESET=4. INFO and RESET have no payload; bytes 1 through 7 must be zero.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t command;

    /**
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint64_t info_reserved;

    /**
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint64_t reset_reserved;

    /**
     * BEGIN: total packaged MCUboot image length including 512-byte header and TLVs. Current allowed range is 560 through 196608 bytes. Bytes 5 through 7 must be zero.
     *
     * Range: 0..4294967295 (0..4294967295 bytes)
     * Scale: 1
     * Offset: 0
     */
    uint32_t image_length;

    /**
     * DATA: byte offset from the beginning of the packaged image, starting at zero and increasing by four. Only an exact retry of the most recent DATA frame is accepted without programming again.
     *
     * Range: 0..16777215 (0..16777215 bytes)
     * Scale: 1
     * Offset: 0
     */
    uint32_t image_offset;

    /**
     * END: Python zlib.crc32 over the complete packaged image. Reflected polynomial 0xEDB88320, initial and final XOR 0xFFFFFFFF. Bytes 5 through 7 must be zero.
     *
     * Range: 0..4294967295 (0..4294967295 -)
     * Scale: 1
     * Offset: 0
     */
    uint32_t image_crc32;

    /**
     * DATA: first payload byte, at ImageOffset.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t payload_byte0;

    /**
     * DATA: second payload byte; use 0xFF if beyond ImageLength.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t payload_byte1;

    /**
     * DATA: third payload byte; use 0xFF if beyond ImageLength.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t payload_byte2;

    /**
     * DATA: fourth payload byte; use 0xFF if beyond ImageLength.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t payload_byte3;
};

/**
 * Signals in message BootloaderResponse.
 *
 * Bootloader to uploader. Byte 0 is request command OR 0x80. An error reply uses the same layout.
 *
 * All signal values are as on the CAN bus.
 */
struct bootloader_bootloader_response_t {
    /**
     * The acknowledged request command OR 0x80. Unknown command errors may carry other values.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t reply_command;

    /**
     * 0=OK, 1=bad DLC/unknown command, 2=bad state, 3=bad image size, 4=unexpected DATA offset, 5=flash/commit failure, 6=CRC/image/SHA validation failure.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t status;

    /**
     * INFO reply (0x80): maximum packaged upload size, currently 196608. Every other reply: accepted byte count for the current upload, including error replies.
     *
     * Range: 0..4294967295 (0..4294967295 bytes)
     * Scale: 1
     * Offset: 0
     */
    uint32_t value_bytes;

    /**
     * Current wire protocol version is 1.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t protocol_version;

    /**
     * 0=idle, 1=receiving, 2=validated and committed; installed into the application slot at next boot. State 2 does not confirm that the application has run.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t update_state;
};

/**
 * Signals in message ENTER_BOOT.
 *
 * Uploader to running application. Standard CAN ID 0x601, DLC 8. Send BCI_BOOT=1 once before polling bootloader INFO. Set all other bits to zero; no entry acknowledgement is defined.
 *
 * All signal values are as on the CAN bus.
 */
struct bootloader_enter_boot_t {
    /**
     * 1 requests bootloader entry. Application must set RAM flag 0xB00710AD at 0x2003FFFC and reset; 0 means no request.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bci_boot;
};

/**
 * Signals in message BCI_BOOT_HEARTBEAT.
 *
 * Bootloader-mode indication on standard ID 0x581, DLC 8. Normally every 500 ms; blocking flash operations can delay it. Bytes 5-7 contain mandatory bootloader version major/minor/patch. Sent at startup, every 500 ms normally, and after INFO replies.
 *
 * All signal values are as on the CAN bus.
 */
struct bootloader_bci_boot_heartbeat_t {
    /**
     * Always 0x55 (decimal 85) while in bootloader mode.
     *
     * Range: 85..85 (85..85 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t boot;

    /**
     * HAL_GetTick() milliseconds sampled when queuing the heartbeat. Unsigned 32-bit little-endian in bytes 1-4; resets on MCU startup and wraps modulo 2^32.
     *
     * Range: 0..4294967295 (0..4294967295 ms)
     * Scale: 1
     * Offset: 0
     */
    uint32_t timestamp;

    /**
     * Mandatory bootloader version, defined in boot_update.h; independent of application version.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t boot_version_major;

    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t boot_version_minor;

    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t boot_version_patch;
};

/**
 * Signals in message BCI_BOOT_INFO.
 *
 * Bootloader capabilities snapshot at startup and after INFO. BoardType 2 identifies the LART STM32F412RE port; ValidBanks bit 0 = valid application (primary) slot, bit 1 = valid committed image in the staging (upload) slot. Firmware remains unsigned in this build.
 *
 * All signal values are as on the CAN bus.
 */
struct bootloader_bci_boot_info_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t protocol_version;

    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t board_type;

    /**
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t valid_banks;

    /**
     * Range: 0..5 (0..5 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t upload_stage;

    /**
     * Range: 0..4294967295 (0..4294967295 bytes)
     * Scale: 1
     * Offset: 0
     */
    uint32_t max_upload_bytes;
};

/**
 * Signals in message BCI_BOOT_FIRMWARE_VERSION.
 *
 * Selected application MCUboot version: major/minor/revision/build. Only sent with a selected valid image. Associate with SelectedBank in BCI_BOOT_DECISION; it is not proof the app has run.
 *
 * All signal values are as on the CAN bus.
 */
struct bootloader_bci_boot_firmware_version_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t major;

    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t minor;

    /**
     * Range: 0..65535 (0..65535 -)
     * Scale: 1
     * Offset: 0
     */
    uint16_t revision;

    /**
     * Range: 0..4294967295 (0..4294967295 -)
     * Scale: 1
     * Offset: 0
     */
    uint32_t build;
};

/**
 * Signals in message BCI_BOOT_DECISION.
 *
 * Startup selection snapshot. Bank 0 means none, 1 the application (primary) slot, 2 the staging (upload) slot. EntryFlags bits: 0=RAM request, 1=button held, 2=no valid image/recovery, 3=rollback. ResetFlags is RCC_CSR captured before reset flags are cleared.
 *
 * All signal values are as on the CAN bus.
 */
struct bootloader_bci_boot_decision_t {
    /**
     * Range: 0..2 (0..2 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t selected_bank;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t entry_flags;

    /**
     * Range: 0..2 (0..2 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t rejected_bank;

    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t reject_reason;

    /**
     * Raw STM32F412 RCC_CSR; reset flags can be combined. Decode using the target reference manual.
     *
     * Range: 0..4294967295 (0..4294967295 -)
     * Scale: 1
     * Offset: 0
     */
    uint32_t reset_flags;
};

/**
 * Signals in message BCI_BOOT_UPLOAD_STATUS.
 *
 * Upload stage changes and progress every 16 KiB or final byte; INFO requests current counts. Counts include header and TLVs. COMMITTED means validated/record committed, not application health confirmation.
 *
 * All signal values are as on the CAN bus.
 */
struct bootloader_bci_boot_upload_status_t {
    /**
     * Range: 0..2 (0..2 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t target_bank;

    /**
     * Range: 0..5 (0..5 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t stage;

    /**
     * Range: 0..16777215 (0..16777215 bytes)
     * Scale: 1
     * Offset: 0
     */
    uint32_t received_bytes;

    /**
     * Range: 0..16777215 (0..16777215 bytes)
     * Scale: 1
     * Offset: 0
     */
    uint32_t total_bytes;
};

/**
 * Signals in message BCI_BOOT_ERROR.
 *
 * Latest error retained until MCU reset. Command 255 means startup/no command. Source identifies validation/upload/flash/CAN/boot. Detail is interpreted using ErrorCode; read the protocol guide. Changes coalesce under TX backpressure.
 *
 * All signal values are as on the CAN bus.
 */
struct bootloader_bci_boot_error_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t error_code;

    /**
     * Range: 0..2 (0..2 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bank;

    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t command;

    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t source;

    /**
     * HEADER/HASH/READ/WRITE/ERASE/UNLOCK/LOCK/RECORD: flash offset; TLV: TLV offset; VECTORS: PC; CRC: device CRC; BAD_FRAME: DLC; BAD_STATE/INACTIVITY/FLASH_OPERATION: byte count; BAD_SIZE: requested length; BAD_OFFSET: requested offset; CAN_QUEUE/TIMEOUT: HAL CAN error; HANDOFF: rejected PC/offset; FLASH_CONFIG: FLASH_OPTCR.
     *
     * Range: 0..4294967295 (0..4294967295 -)
     * Scale: 1
     * Offset: 0
     */
    uint32_t detail;
};

/**
 * Signals in message BCI_BOOT_ROLLBACK.
 *
 * The committed, not yet installed staged image failed validation, so the current application slot image was kept. Reason is the validation error. RejectedGeneration is 0 on the F412 (no upload generations). RejectedVersionKnown permits the companion unverified header version on 0x589.
 *
 * All signal values are as on the CAN bus.
 */
struct bootloader_bci_boot_rollback_t {
    /**
     * Range: 0..2 (0..2 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t rejected_bank;

    /**
     * Range: 0..2 (0..2 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t selected_bank;

    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t reason;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t rejected_version_known;

    /**
     * Range: 0..4294967295 (0..4294967295 -)
     * Scale: 1
     * Offset: 0
     */
    uint32_t rejected_generation;
};

/**
 * Signals in message BCI_BOOT_FLASH_ERROR.
 *
 * Details accompanying a flash-source error: device-relative offset (add flash base for physical address) and raw HAL_FLASH_GetError bits. No private/signing key material is transmitted.
 *
 * All signal values are as on the CAN bus.
 */
struct bootloader_bci_boot_flash_error_t {
    /**
     * Range: 0..4294967295 (0..4294967295 bytes)
     * Scale: 1
     * Offset: 0
     */
    uint32_t flash_offset;

    /**
     * Range: 0..4294967295 (0..4294967295 -)
     * Scale: 1
     * Offset: 0
     */
    uint32_t hal_error;
};

/**
 * Signals in message BCI_BOOT_REJECTED_VERSION.
 *
 * Unverified MCUboot header version from the rejected image, only when RejectedVersionKnown=1. Never interpret it as an authenticated or successfully running version.
 *
 * All signal values are as on the CAN bus.
 */
struct bootloader_bci_boot_rejected_version_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t major;

    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t minor;

    /**
     * Range: 0..65535 (0..65535 -)
     * Scale: 1
     * Offset: 0
     */
    uint16_t revision;

    /**
     * Range: 0..4294967295 (0..4294967295 -)
     * Scale: 1
     * Offset: 0
     */
    uint32_t build;
};

